static inline bool ts_lex_set_contains_with_ascii(
  const uint32_t *ascii,
  const TSCharacterRange *ranges,
  uint32_t len,
  int32_t lookahead
) {
  if ((uint32_t)lookahead < 128) {
    return (ascii[lookahead / 32] >> (lookahead % 32)) & 1;
  }
  return len && set_contains(ranges, len, lookahead);
}
static const uint16_t ts_lex_advance_map_0[] = {
  '.', 300,
  '0', 297,
  'B', 116,
  'E', 114,
  'O', 117,
  'X', 125,
  '_', 120,
  'b', 116,
  'e', 114,
  'n', 291,
  'o', 117,
  'x', 125,
};

#define TS_LEX_ADVANCE_MAP_SORTED(map)                                      \
  {                                                                 \
    uint32_t low = 0;                                                \
    uint32_t high = sizeof(map) / sizeof(map[0]) / 2;                 \
    while (low < high) {                                             \
      uint32_t mid = low + (high - low) / 2;                          \
      if (map[mid * 2] < lookahead) {                                \
        low = mid + 1;                                              \
      } else if (map[mid * 2] > lookahead) {                          \
        high = mid;                                                 \
      } else {                                                      \
        state = map[mid * 2 + 1];                                    \
        goto next_state;                                            \
      }                                                             \
    }                                                               \
  }

#define TS_LEX_ADVANCE_MAP_DENSE(first, map)                                \
  {                                                                 \
    uint32_t index = (uint32_t)lookahead - (first);                   \
    if (index < sizeof(map) / sizeof(map[0]) && map[index] != UINT16_MAX) { \
      state = map[index];                                            \
      goto next_state;                                              \
    }                                                               \
  }

